#### Problem 1 ########
#$$$$$$$$$$$$$$$$$$$$$$

# read file raw
loadedFCS <- read.FCS("course/03_InsideFCSFile/data/CellCounts4L_AB_05_ND050_05.fcs", transformation = FALSE, truncate_max_range = FALSE)

# name flowframe
myflowframe <- flowFrame(loadedFCS@exprs)

##### unmixed file ---

# read file unmixed
loadedFCS_unmixed <- read.FCS("course/03_InsideFCSFile/data/AdditionalFCSFiles/2025_07_26_AB_02_NY068_02_Ctrl.fcs", transformation = FALSE, truncate_max_range = FALSE)

#flow
myflowframe_unmixed <- flowFrame(loadedFCS_unmixed@exprs)

#### comparison

#### check dimension of flowFrames
dim(myflowframe) # 100 event and 61 parameters
dim(myflowframe_unmixed) # 100 event and 43 parameters

##### verify colnames
colnames(myflowframe)
colnames(myflowframe_unmixed)
# here, I realized that after unmixing the samples changed channel names to the markers/fluorochromes used in the study

compare(loadedFCS, loadedFCS_unmixed)
compare(myflowframe, myflowframe_unmixed)

myflowframe@exprs
myflowframe_unmixed@exprs

myflowframe@parameters #### different number of rowNames = 61
myflowframe_unmixed@parameters #### different number of rowNames = 43

length(myflowframe@description) #443
length(myflowframe_unmixed@description) #317

#### use this code to find differences in flowframe descriptions
setdiff(myflowframe@description, myflowframe_unmixed@description)

###### conclusion Problem 1 ######
# channes were renamed and were only preserved "used" fluorochromes in the experiment. 
# Hence, the number of parameters was reduced from 61 to 43, impacting directly the number 
# of items in the flowframe@description

